class CustomerProfileScreen extends StatefulWidget {
  const CustomerProfileScreen({super.key});

  @override
  State<CustomerProfileScreen> createState() => _CustomerProfileScreenState();
}

class _CustomerProfileScreenState extends State<CustomerProfileScreen> {
  bool _isEditingPhone = false;
  late TextEditingController _phoneController;
  late TextEditingController _nameController;

  @override
  void initState() {
    super.initState();
    final c = JeebliProvider.of(context, listen: false);
    _phoneController = TextEditingController(text: c.customerPhone);
    _nameController = TextEditingController(
        text: c.customerName.isNotEmpty ? c.customerName : 'زبون جيب لي');
  }

  @override
  void dispose() {
    _phoneController.dispose();
    _nameController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final controller = JeebliProvider.of(context);
    final name = controller.customerName.isNotEmpty ? controller.customerName : 'زبون جيب لي';
    final phone = controller.customerPhone;
    final location = controller.selectedNeighborhood.isNotEmpty
        ? controller.selectedNeighborhood
        : 'لم يُحدد بعد';
    final orderCount = controller.notifications.length; // تقريب لعدد الطلبات السابقة

    return Scaffold(
      backgroundColor: const Color(0xFFF8FAFB),
      appBar: AppBar(
        title: const Text('الملف الشخصي', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 16)),
        centerTitle: true,
        backgroundColor: Colors.white,
        foregroundColor: const Color(0xFF1E293B),
        elevation: 0,
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(1),
          child: Container(height: 1, color: Colors.grey.withOpacity(0.1)),
        ),
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            const SizedBox(height: 12),

            // ===== قسم الصورة الشخصية =====
            Stack(
              alignment: Alignment.bottomRight,
              children: [
                Container(
                  width: 96,
                  height: 96,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    gradient: const LinearGradient(
                      colors: [Color(0xFFE65100), Color(0xFFFF8A65)],
                      begin: Alignment.topLeft,
                      end: Alignment.bottomRight,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: const Color(0xFFE65100).withOpacity(0.3),
                        blurRadius: 16,
                        offset: const Offset(0, 6),
                      )
                    ],
                  ),
                  child: Center(
                    child: Text(
                      name.isNotEmpty ? name[0].toUpperCase() : '؟',
                      style: const TextStyle(
                          fontSize: 38, fontWeight: FontWeight.bold, color: Colors.white),
                    ),
                  ),
                ),
                // زر تعديل الصورة
                GestureDetector(
                  onTap: () {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(
                        content: Text('📷 ميزة رفع الصورة ستُفعَّل قريباً (Firebase Storage)'),
                        behavior: SnackBarBehavior.floating,
                      ),
                    );
                  },
                  child: Container(
                    width: 28,
                    height: 28,
                    decoration: BoxDecoration(
                      color: Colors.white,
                      shape: BoxShape.circle,
                      boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 6)],
                    ),
                    child: const Icon(Icons.camera_alt_rounded, size: 14, color: Color(0xFFE65100)),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 12),

            // الاسم
            Text(name,
                style: const TextStyle(
                    fontSize: 20, fontWeight: FontWeight.bold, color: Color(0xFF1E293B))),
            const SizedBox(height: 4),
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 3),
              decoration: BoxDecoration(
                color: Colors.green[50],
                borderRadius: BorderRadius.circular(20),
                border: Border.all(color: Colors.green[100]!),
              ),
              child: Text(
                '🟢 حساب زبون نشط في الهاشمية',
                style: TextStyle(color: Colors.green[800], fontSize: 10.5, fontWeight: FontWeight.bold),
              ),
            ),
            const SizedBox(height: 20),

            // ===== إحصائيات سريعة =====
            Row(
              children: [
                _buildStatCard('طلب', orderCount.toString(), Icons.shopping_bag_outlined),
                const SizedBox(width: 12),
                _buildStatCard('حي', location.contains('(') ? location.split('(').first.trim() : location.split(' ').first, Icons.location_city_outlined),
                const SizedBox(width: 12),
                _buildStatCard('نقطة', '0', Icons.star_outline_rounded),
              ],
            ),
            const SizedBox(height: 20),

            // ===== بطاقة المعلومات =====
            Container(
              padding: const EdgeInsets.all(18),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(18),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.04),
                    blurRadius: 20,
                    offset: const Offset(0, 4),
                  )
                ],
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text('معلومات الحساب',
                      style: TextStyle(
                          fontSize: 13, fontWeight: FontWeight.bold, color: Color(0xFF1E293B))),
                  const SizedBox(height: 14),

                  // رقم الهاتف (قابل للتعديل)
                  _buildEditablePhoneTile(controller, phone),
                  const Divider(height: 24, thickness: 0.5),

                  // البريد / المعرف
                  _buildInfoTile(
                    Icons.alternate_email_rounded,
                    'المعرف / البريد',
                    controller.userEmailOrPhone ?? phone,
                    color: const Color(0xFF6366F1),
                  ),
                  const Divider(height: 24, thickness: 0.5),

                  // المنطقة
                  _buildInfoTile(
                    Icons.location_on_rounded,
                    'المنطقة المحددة',
                    location,
                    color: const Color(0xFF10B981),
                  ),
                  if (controller.streetDetails.isNotEmpty) ...[
                    const Divider(height: 24, thickness: 0.5),
                    _buildInfoTile(
                      Icons.home_rounded,
                      'نقطة التوصيل',
                      controller.streetDetails,
                      color: const Color(0xFFF59E0B),
                    ),
                  ],
                ],
              ),
            ),
            const SizedBox(height: 20),

            // ===== بطاقة إعدادات التطبيق =====
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 4),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(18),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(0.03),
                    blurRadius: 16,
                    offset: const Offset(0, 4),
                  )
                ],
              ),
              child: Column(
                children: [
                  _buildSettingsTile(Icons.notifications_outlined, 'إشعارات الطلبات', Colors.amber, onTap: () {}),
                  _buildSettingsTile(Icons.history_rounded, 'سجل الطلبات', Colors.indigo, onTap: () {}),
                  _buildSettingsTile(Icons.help_outline_rounded, 'الدعم والمساعدة', Colors.teal, onTap: () {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(
                        content: Text('💬 للتواصل مع الدعم الفني عبر واتساب، اضغط على أي مطعم وأرسل طلبك'),
                        behavior: SnackBarBehavior.floating,
                      ),
                    );
                  }),
                  const Divider(height: 0.5, thickness: 0.5),
                  _buildSettingsTile(Icons.logout_rounded, 'تسجيل الخروج', Colors.red,
                      isDestructive: true, onTap: () => _showLogoutDialog(context, controller)),
                ],
              ),
            ),

            const SizedBox(height: 24),
            Text('جيبلي ديلفري — نسخة 2.0.0',
                style: TextStyle(color: Colors.grey[400], fontSize: 10.5)),
            const SizedBox(height: 8),
          ],
        ),
      ),
    );
  }

  Widget _buildStatCard(String label, String value, IconData icon) {
    return Expanded(
      child: Container(
        padding: const EdgeInsets.symmetric(vertical: 14),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(14),
          boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.03), blurRadius: 12)],
        ),
        child: Column(
          children: [
            Icon(icon, color: const Color(0xFFE65100), size: 22),
            const SizedBox(height: 6),
            Text(value,
                style: const TextStyle(
                    fontWeight: FontWeight.bold, fontSize: 16, color: Color(0xFF1E293B))),
            const SizedBox(height: 2),
            Text(label, style: const TextStyle(color: Colors.grey, fontSize: 10)),
          ],
        ),
      ),
    );
  }

  Widget _buildEditablePhoneTile(JeebliController controller, String phone) {
    return Row(
      children: [
        Container(
          padding: const EdgeInsets.all(8),
          decoration: BoxDecoration(
            color: const Color(0xFFE65100).withOpacity(0.07),
            borderRadius: BorderRadius.circular(10),
          ),
          child: const Icon(Icons.phone_android_rounded, color: Color(0xFFE65100), size: 18),
        ),
        const SizedBox(width: 14),
        Expanded(
          child: _isEditingPhone
              ? TextField(
                  controller: _phoneController,
                  keyboardType: TextInputType.phone,
                  autofocus: true,
                  style: const TextStyle(fontSize: 13, fontWeight: FontWeight.bold),
                  decoration: InputDecoration(
                    hintText: '07XXXXXXXXX',
                    isDense: true,
                    border: OutlineInputBorder(borderRadius: BorderRadius.circular(10)),
                    focusedBorder: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                      borderSide: const BorderSide(color: Color(0xFFE65100)),
                    ),
                    contentPadding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
                  ),
                )
              : Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text('رقم الهاتف', style: TextStyle(fontSize: 11, color: Colors.grey)),
                    Text(phone.isNotEmpty ? phone : 'لم يُدخل',
                        style: const TextStyle(fontSize: 13, fontWeight: FontWeight.bold, color: Color(0xFF1E293B))),
                  ],
                ),
        ),
        const SizedBox(width: 8),
        IconButton(
          onPressed: () {
            if (_isEditingPhone) {
              // حفظ رقم الهاتف الجديد
              final newPhone = _phoneController.text.trim();
              if (newPhone.isNotEmpty && newPhone.length >= 10) {
                controller.updateCustomerPhone(newPhone);
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(
                    content: Text('✅ تم تحديث رقم الهاتف بنجاح!'),
                    behavior: SnackBarBehavior.floating,
                    backgroundColor: Colors.green,
                  ),
                );
              }
            }
            setState(() => _isEditingPhone = !_isEditingPhone);
          },
          icon: Icon(
            _isEditingPhone ? Icons.check_circle_rounded : Icons.edit_outlined,
            color: _isEditingPhone ? Colors.green : const Color(0xFFE65100),
            size: 20,
          ),
          tooltip: _isEditingPhone ? 'حفظ الرقم' : 'تعديل الرقم',
        ),
      ],
    );
  }

  Widget _buildInfoTile(IconData icon, String title, String value, {Color? color}) {
    return Row(
      children: [
        Container(
          padding: const EdgeInsets.all(8),
          decoration: BoxDecoration(
            color: (color ?? const Color(0xFFE65100)).withOpacity(0.07),
            borderRadius: BorderRadius.circular(10),
          ),
          child: Icon(icon, color: color ?? const Color(0xFFE65100), size: 18),
        ),
        const SizedBox(width: 14),
        Expanded(
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(title, style: const TextStyle(fontSize: 11, color: Colors.grey)),
              Text(value,
                  style: const TextStyle(
                      fontSize: 13, fontWeight: FontWeight.bold, color: Color(0xFF1E293B)),
                  overflow: TextOverflow.ellipsis,
                  maxLines: 1),
            ],
          ),
        ),
      ],
    );
  }

  Widget _buildSettingsTile(IconData icon, String label, Color color,
      {bool isDestructive = false, required VoidCallback onTap}) {
    return ListTile(
      onTap: onTap,
      leading: Container(
        padding: const EdgeInsets.all(8),
        decoration: BoxDecoration(
          color: color.withOpacity(0.08),
          borderRadius: BorderRadius.circular(10),
        ),
        child: Icon(icon, color: color, size: 18),
      ),
      title: Text(label,
          style: TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w600,
              color: isDestructive ? Colors.red[600] : const Color(0xFF1E293B))),
      trailing: Icon(Icons.arrow_forward_ios_rounded,
          size: 14, color: isDestructive ? Colors.red[300] : Colors.grey[400]),
    );
  }

  void _showLogoutDialog(BuildContext context, JeebliController controller) {
    showDialog(
      context: context,
      builder: (ctx) => Directionality(
        textDirection: TextDirection.rtl,
        child: AlertDialog(
          shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
          title: const Text('تسجيل الخروج'),
          content: const Text('هل أنت متأكد من رغبتك في تسجيل الخروج؟'),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('إلغاء')),
            ElevatedButton(
              onPressed: () {
                Navigator.pop(ctx);
                controller.logout();
              },
              style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.red, foregroundColor: Colors.white),
              child: const Text('نعم، خروج'),
            ),
          ],
        ),
      ),
    );
  }
}

